// Synthetic host-boundary reports. Real subprocess evidence lives in interrogate-executed.test.ts.
export const frozenProof = { revision: 'a'.repeat(40), tree: 'b'.repeat(40), patchDigest: 'c'.repeat(64), files: [{path:'src/retry.ts', sha256:'d'.repeat(64)}] };
export const proof = (scratch = '/task/reviewer-a') => ({ command: 'node repro.mjs', cwd: scratch, scratch, environment: [], frozen: structuredClone(frozenProof), frozenAfter: structuredClone(frozenProof), outcome: 'observed', repro: [{path:'repro.mjs', sha256:'e'.repeat(64)}], safety:'Inspected local assertion only; no external access', exitCode:1, expectedExitCode:0, actual:'400 is retryable', expected:'400 is not retryable' });
export const executedFinding = (severity = 'warning') => ({ id:'F1', severity, location:'src/retry.ts:12', claim:'Client errors retry', proof:proof() });
export const executedReviewer = (findings = []) => ({intent:'Parser must reject unterminated strings', frozen:structuredClone(frozenProof), coverage:'Local fixture assertions', findings});
export const executedFrame = {intent:'Parser must reject unterminated strings', 'frozen-head':JSON.stringify(frozenProof), 'reproduction-policy':'Local owned scratch, inspected command, no network'};
export const leadFor = (input) => { const context = structuredClone(input); return ({intent:'Parser must reject unterminated strings', frozen:context.frozen, reviewers:context.reviewers.map(({slot,artifactDigest}) => ({slot,artifactDigest})), accounting:context.reviewers.flatMap(r => r.output.findings.map(f => ({origin:r.slot+'/'+f.id, disposition:'keep', reason:'Reproduced independently in rebuilt scratch', rerun:{...f.proof,scratch:'/task/lead-'+r.slot.replace(':','-')+'-'+f.id,cwd:'/task/lead-'+r.slot.replace(':','-')+'-'+f.id}})))}); };
export const contextFromBrief = task => { const lines = task.split(String.fromCharCode(10)); return JSON.parse(lines[lines.findIndex(line => line.startsWith('Frozen proof context')) + 2]); };
